/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: fixturePath, upload, diskUpload, withoutTotalSamples, pcmWav, withId3Prefix, fakeDecoder
 *   Constants: listingOrProgress
 * Tests
 *   - lossless sources rooms reject still yield their exact decoded duration
 *   - a FLAC header that overstates its length cannot change the decoded duration
 *   - many-channel high-resolution WAV longer than one re-chunked frame is measured
 *   - unrecognized, corrupt, truncated and size-mismatched sources have no probed duration
 *   - a missing decoder stays retryable and cancellation is rethrown
 *   - each probe forces the one demuxer its leading bytes name, and room decoding keeps its own whitelist and stream cap
 *   - a probed duration adds up the decoded packets, whatever FFmpeg reports as progress
 *   - a decoded timeline beyond the 24-hour bound is rejected without a duration
 * @end-catalog */

import assert from 'node:assert/strict';
import childProcess, { type SpawnOptions } from 'node:child_process';
import { mkdtemp, readFile, rm, stat, writeFile } from 'node:fs/promises';
import { syncBuiltinESMExports } from 'node:module';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import test, { type TestContext } from 'node:test';
import { probeAudioDurationMs } from '../../src/services/roomAudio/audioDurationProbe';
import { inspectRoomAudioFile, RoomAudioInspectionError } from '../../src/services/roomAudio/roomAudioInspection';
import { wavUploadFile } from '../support/pcmWav';

const fixturePath = (name: string) => resolve('test/fixtures/room-audio', name);
const upload = (buffer: Buffer) => ({ ...wavUploadFile(buffer), originalname: 'misleading.mp3', mimetype: 'application/octet-stream' });
const diskUpload = async (name: string) => ({ ...upload(Buffer.alloc(0)), path: fixturePath(name), size: (await stat(fixturePath(name))).size });

/** STREAMINFO keeps its 36-bit total sample count in the low nibble of byte 21 and bytes 22–25; zero means unknown. */
const withoutTotalSamples = (flac: Buffer) => {
    const bytes = Buffer.from(flac);
    assert.equal(bytes.toString('latin1', 0, 4), 'fLaC');
    bytes[21] &= 0xf0; bytes.fill(0, 22, 26);
    return bytes;
};
/** A silent integer PCM WAV of any shape, written to disk; the probe decodes it, so only the header must be right. */
const pcmWav = async (directory: string, channels: number, bits: number, rate: number, frames: number) => {
    const blockAlign = channels * bits / 8;
    const header = Buffer.alloc(44);
    header.write('RIFF', 0, 'latin1'); header.writeUInt32LE(36 + frames * blockAlign, 4); header.write('WAVEfmt ', 8, 'latin1');
    header.writeUInt32LE(16, 16); header.writeUInt16LE(1, 20); header.writeUInt16LE(channels, 22); header.writeUInt32LE(rate, 24);
    header.writeUInt32LE(rate * blockAlign, 28); header.writeUInt16LE(blockAlign, 32); header.writeUInt16LE(bits, 34);
    header.write('data', 36, 'latin1'); header.writeUInt32LE(frames * blockAlign, 40);
    const path = join(directory, `pcm-${channels}x${bits}.wav`);
    await writeFile(path, Buffer.concat([header, Buffer.alloc(frames * blockAlign)]));
    return { ...upload(Buffer.alloc(0)), path, size: (await stat(path)).size };
};
/** An ID3v2.4 tag of `padding` zero bytes in front of the stream, as some taggers write. */
const withId3Prefix = (bytes: Buffer, padding = 20) => Buffer.concat([Buffer.from([0x49, 0x44, 0x33, 4, 0, 0, 0, 0, 0, padding]), Buffer.alloc(padding), bytes]);

/** Runs a Node script as the decoder with the arguments it was given, and records them; streams and process cleanup stay real. */
const fakeDecoder = async (context: TestContext, source: string) => {
    const directory = await mkdtemp(join(tmpdir(), 'archtree-duration-probe-'));
    const path = join(directory, 'decoder.cjs');
    await writeFile(path, source);
    const previous = process.env.ROOM_AUDIO_FFMPEG_PATH;
    process.env.ROOM_AUDIO_FFMPEG_PATH = path;
    const calls: string[][] = [];
    const originalSpawn = childProcess.spawn;
    const spawnMock = context.mock.method(childProcess, 'spawn', (command: string, args?: readonly string[], options?: SpawnOptions) => {
        if (command !== path) return originalSpawn(command, args ?? [], options ?? {});
        calls.push([...(args ?? [])]);
        return originalSpawn(process.execPath, [path, ...(args ?? [])], options ?? {});
    });
    syncBuiltinESMExports();
    return {
        calls,
        async restore() {
            spawnMock.mock.restore(); syncBuiltinESMExports();
            if (previous === undefined) delete process.env.ROOM_AUDIO_FFMPEG_PATH; else process.env.ROOM_AUDIO_FFMPEG_PATH = previous;
            await rm(directory, { recursive: true, force: true });
        }
    };
};

// These synthetic tones run the real decoder; a missing FFmpeg runtime is a failed prerequisite.
test('lossless sources rooms reject still yield their exact decoded duration', async () => {
    for (const name of ['tone.flac', 'tone-covers.flac', 'tone-alac.m4a', 'tone.aiff', 'tone-24bit.wav']) {
        const file = await diskUpload(name);
        assert.equal(await inspectRoomAudioFile(file), null, `${name} stays outside rooms`);
        assert.equal(await probeAudioDurationMs(file), 2000, name);
    }
    const flac = await readFile(fixturePath('tone.flac'));
    assert.equal(await probeAudioDurationMs(upload(flac)), 2000, 'buffered uploads decode from a private temporary file');
    assert.equal(await probeAudioDurationMs(upload(withoutTotalSamples(flac))), 2000, 'an unknown STREAMINFO total is measured, not trusted');
    assert.equal(await probeAudioDurationMs(upload(withId3Prefix(flac))), 2000, 'an ID3v2 tag before the FLAC marker is skipped');
});

test('a FLAC header that overstates its length cannot change the decoded duration', async () => {
    const bytes = Buffer.from(await readFile(fixturePath('tone.flac')));
    const total = (bytes[21] & 0x0f) * 2 ** 32 + bytes.readUInt32BE(22);
    assert.equal(total, 88200);
    bytes.writeUInt32BE(total * 2, 22);
    assert.equal(await probeAudioDurationMs(upload(bytes)), 2000);
});

test('many-channel high-resolution WAV longer than one re-chunked frame is measured', async () => {
    const directory = await mkdtemp(join(tmpdir(), 'archtree-duration-probe-'));
    try { assert.equal(await probeAudioDurationMs(await pcmWav(directory, 32, 32, 8000, 270_000)), 33_750); }
    finally { await rm(directory, { recursive: true, force: true }); }
});

test('unrecognized, corrupt, truncated and size-mismatched sources have no probed duration', async () => {
    const flac = await readFile(fixturePath('tone.flac'));
    const corrupt = Buffer.from(flac); corrupt.fill(0x55, corrupt.length - 4096, corrupt.length - 2048);
    for (const [label, bytes] of [
        ['junk', Buffer.from('not actually decoded audio data')],
        ['truncated', flac.subarray(0, flac.length - 1000)],
        ['corrupt frames', corrupt],
        ['ID3 without FLAC', withId3Prefix(Buffer.from('not a FLAC stream at all'))],
        ['oversized ID3 tag', Buffer.concat([Buffer.from([0x49, 0x44, 0x33, 4, 0, 0, 0x7f, 0x7f, 0x7f, 0x7f]), flac])],
        ['MP3 frames', await readFile(fixturePath('cbr.mp3'))]
    ] as const) assert.equal(await probeAudioDurationMs(upload(bytes)), null, label);
    const mismatched = await diskUpload('tone.flac'); mismatched.size += 1;
    assert.equal(await probeAudioDurationMs(mismatched), null);
});

test('a missing decoder stays retryable and cancellation is rethrown', async () => {
    const previous = process.env.ROOM_AUDIO_FFMPEG_PATH;
    try {
        process.env.ROOM_AUDIO_FFMPEG_PATH = '/nonexistent/archtree-test-ffmpeg';
        await assert.rejects(probeAudioDurationMs(await diskUpload('tone.flac')),
            (error: unknown) => error instanceof RoomAudioInspectionError && error.code === 'decoder_unavailable');
    } finally { if (previous === undefined) delete process.env.ROOM_AUDIO_FFMPEG_PATH; else process.env.ROOM_AUDIO_FFMPEG_PATH = previous; }
    await assert.rejects(probeAudioDurationMs(await diskUpload('tone.flac'), { signal: AbortSignal.abort() }), { name: 'AbortError' });
});

/**
 * A fake decoder answering room decoding with progress and a probe with a packet listing whose last packet starts at
 * 1996.9 ms and ends at 2000 ms: FFmpeg before 7.0 reports the start as its final progress.
 */
const listingOrProgress = `process.stdout.write(process.argv.includes('framecrc')
    ? '#software: Lavf60.16.100\\n#tb 0: 1/44100\\n#media_type 0: audio\\n0,          0,          0,    88064,   352256, 0x00000000\\n'
        + '0,      88064,      88064,      136,      544, 0x00000000\\n'
    : 'out_time_us=1996916\\nprogress=end\\n');
`;

test('each probe forces the one demuxer its leading bytes name, and room decoding keeps its own whitelist and stream cap', async context => {
    const decoder = await fakeDecoder(context, listingOrProgress);
    try {
        for (const [name, demuxer] of [['tone.flac', 'flac'], ['tone-alac.m4a', 'mov'], ['tone.aiff', 'aiff'], ['tone-24bit.wav', 'wav']]) {
            assert.equal(await probeAudioDurationMs(await diskUpload(name)), 2000, name);
            const args = decoder.calls.at(-1)!;
            assert.equal(args[args.indexOf('-f') + 1], demuxer, name);
            assert.equal(args[args.indexOf('-format_whitelist') + 1], demuxer, name);
            assert.equal(args[args.indexOf('-protocol_whitelist') + 1], 'file,pipe', name);
            assert.equal(args[args.indexOf('-max_streams') + 1], '8', name);
        }
        assert.deepEqual(await inspectRoomAudioFile(await diskUpload('cbr.mp3')), { durationMs: 2000, format: 'mp3' });
        const room = decoder.calls.at(-1)!;
        assert.equal(room[room.indexOf('-f') + 1], 'mp3');
        assert.equal(room[room.indexOf('-format_whitelist') + 1], 'mp3,mov');
        assert.equal(room[room.indexOf('-max_streams') + 1], '2');
    } finally { await decoder.restore(); }
});

test('a probed duration adds up the decoded packets, whatever FFmpeg reports as progress', async context => {
    const decoder = await fakeDecoder(context, listingOrProgress);
    try {
        assert.equal(await probeAudioDurationMs(await diskUpload('tone.flac')), 2000);
        const probe = decoder.calls.at(-1)!;
        assert.deepEqual(probe.slice(probe.indexOf('-af')), ['-af', 'pan=mono|c0=c0,asetnsamples=n=262144:p=0', '-f', 'framecrc', '-']);
        assert.equal(probe.includes('-progress'), false);
        await inspectRoomAudioFile(await diskUpload('cbr.mp3'));
        const room = decoder.calls.at(-1)!;
        assert.deepEqual(room.slice(room.indexOf('-progress')), ['-progress', 'pipe:1', '-f', 'null', '-']);
    } finally { await decoder.restore(); }
    const unanchored = await fakeDecoder(context, "process.stdout.write('0,          0,          0,    88200,   352800, 0x00000000\\n');\n");
    try { assert.equal(await probeAudioDurationMs(await diskUpload('tone.flac')), null, 'a packet before its time base is not measured'); }
    finally { await unanchored.restore(); }
    // 200 packets of 0.1 s in a single write of about 12 KiB, with a 1 s timestamp gap halfway that adds no audio.
    const burst = await fakeDecoder(context, `const lines = ['#tb 0: 1/44100'];
for (let index = 0; index < 200; index++) {
    const dts = String(index * 4410 + (index >= 100 ? 44100 : 0)).padStart(10);
    lines.push(\`0, \${dts}, \${dts},     4410,    17640, 0x00000000\`);
}
process.stdout.write(lines.join('\\n') + '\\n');
`);
    try { assert.equal(await probeAudioDurationMs(await diskUpload('tone.flac')), 20_000, 'a long listing in one read and a timestamp gap'); }
    finally { await burst.restore(); }
});

test('a decoded timeline beyond the 24-hour bound is rejected without a duration', async context => {
    const decoder = await fakeDecoder(context, "process.stdout.write('#tb 0: 1/1000\\n0, 0, 0, 86400200, 1, 0x00000000\\n'); setInterval(() => {}, 1000);\n");
    try { assert.equal(await probeAudioDurationMs(await diskUpload('tone.flac')), null); }
    finally { await decoder.restore(); }
});
